// Packages: AWSSDK.DynamoDBv2, Amazon.DynamoDBv2
using Amazon.DynamoDBv2;
using Amazon.DynamoDBv2.Model;

public class DynamoDbPostService
{
    private readonly IAmazonDynamoDB _dynamoDb;
    private const string TableName = "Posts";

    public DynamoDbPostService(IAmazonDynamoDB dynamoDb)
    {
        _dynamoDb = dynamoDb;
    }

    public async Task CreatePostAsync(Post post, CancellationToken cancellationToken = default)
    {
        try
        {
            var request = new PutItemRequest
            {
                TableName = TableName,
                Item = new Dictionary<string, AttributeValue>
                {
                    { "Id", new AttributeValue { S = post.Id.ToString() } },
                    { "Title", new AttributeValue { S = post.Title } },
                    { "Content", new AttributeValue { S = post.Content } },
                    { "PublishedAt", new AttributeValue { N = post.PublishedAt.ToUnixTimeSeconds().ToString() } }
                }
            };

            PutItemResponse response = await _dynamoDb.PutItemAsync(request, cancellationToken);
            Console.WriteLine($"Created post {post.Id} (ConsumedCapacity: {response.ConsumedCapacity.CapacityUnits})");
        }
        catch (AmazonDynamoDBException ex)
        {
            Console.WriteLine($"DynamoDB error: {ex.Message}");
            throw;
        }
    }

    public async Task<Post?> GetPostAsync(Guid id, CancellationToken cancellationToken = default)
    {
        try
        {
            var request = new GetItemRequest
            {
                TableName = TableName,
                Key = new Dictionary<string, AttributeValue>
                {
                    { "Id", new AttributeValue { S = id.ToString() } }
                }
            };

            GetItemResponse response = await _dynamoDb.GetItemAsync(request, cancellationToken);

            if (response.Item is null || response.Item.Count == 0)
            {
                Console.WriteLine($"Post {id} not found");
                return null;
            }

            return new Post
            {
                Id = Guid.Parse(response.Item["Id"].S),
                Title = response.Item["Title"].S,
                Content = response.Item["Content"].S,
                PublishedAt = DateTimeOffset.FromUnixTimeSeconds(long.Parse(response.Item["PublishedAt"].N)).DateTime
            };
        }
        catch (AmazonDynamoDBException ex)
        {
            Console.WriteLine($"DynamoDB error: {ex.Message}");
            throw;
        }
    }

    public async Task DeletePostAsync(Guid id, CancellationToken cancellationToken = default)
    {
        try
        {
            var request = new DeleteItemRequest
            {
                TableName = TableName,
                Key = new Dictionary<string, AttributeValue>
                {
                    { "Id", new AttributeValue { S = id.ToString() } }
                }
            };

            DeleteItemResponse response = await _dynamoDb.DeleteItemAsync(request, cancellationToken);
            Console.WriteLine($"Deleted post {id} (RequestId: {response.ResponseMetadata.RequestId})");
        }
        catch (AmazonDynamoDBException ex)
        {
            Console.WriteLine($"DynamoDB error: {ex.Message}");
            throw;
        }
    }
}

