// Packages: AWSSDK.DynamoDBv2, Amazon.DynamoDBv2
using Amazon.DynamoDBv2;
using Amazon.DynamoDBv2.Model;

public static async Task QueryPostsByTitleAsync(string titlePrefix, CancellationToken cancellationToken = default)
{
    try
    {
        var dynamoDb = new AmazonDynamoDBClient(RegionEndpoint.USEast1);

        var query = new QueryRequest
        {
            TableName = "Posts",
            IndexName = "TitleIndex", // Assuming a GSI on Title
            KeyConditionExpression = "begins_with(Title, :prefix)",
            ExpressionAttributeValues = new Dictionary<string, AttributeValue>
            {
                { ":prefix", new AttributeValue { S = titlePrefix } }
            }
        };

        QueryResponse queryResponse = await dynamoDb.QueryAsync(query, cancellationToken);
        Console.WriteLine($"Found {queryResponse.Count} posts matching '{titlePrefix}'");

        foreach (var item in queryResponse.Items)
        {
            Console.WriteLine($"Title: {item["Title"].S}");
        }
    }
    catch (AmazonDynamoDBException ex)
    {
        Console.WriteLine($"Query error: {ex.Message}");
        throw;
    }
}

